976	      throw new Error(`the retry must write exactly one ingested row, found ${state.events.length}`);
977	    }
978	    const lookup = state.runLookups?.[0]?.searchParams;
979	    if (lookup?.get("id") !== `eq.${runId}` || lookup.get("call_events.kind") !== "eq.ingested") {
980	      throw new Error("the backfill must look for this run's ingested row");
981	    }
982	    const event = state.events[0];
983	    const detail = event.detail as Record<string, unknown>;
984	    if (event.kind !== "ingested" || detail.backfilled !== true || detail.calle_call_id !== "call_lost_event") {
985	      throw new Error("the backfilled row must be marked and name the call");
986	    }
987	    if (detail.item_count !== 1 || detail.mention_count !== 3 || detail.retirement_count !== 1 || detail.commitment_count !== 1) {
988	      throw new Error("the backfilled row must carry the counts of the committed rows");
989	    }
990	  });
991	
992	  testFn("an RPC failure names its cause without a phone number or a key", async () => {
993	    const key = "REDACTED";
994	    const state: MockState = {
