1	-- T2.7: Turning a terminal call into rows must be one transaction. PostgREST
2	-- cannot hold a transaction across several REST calls, so ingestion lives in
3	-- this function. It locks the run, then writes the transcript, the result, the
4	-- items, their mentions, the retirements and the commitments in one unit.
5	-- A second ingest for the same run waits on the lock, then returns the
6	-- already_ingested marker and changes nothing.
7	create function public.ingest_call_result(
8	  p_call_run_id uuid,
9	  p_user_id uuid,
10	  p_transcript_turns jsonb,
11	  p_raw jsonb,
12	  p_structured jsonb,
13	  p_result_valid boolean,
14	  p_result_error text,
15	  p_state text,
16	  p_disposition text,
17	  p_mood text,
18	  p_completed_at timestamptz
19	)
20	returns jsonb
21	language plpgsql
22	security definer
23	set search_path = ''
24	as $$
25	declare
26	  v_run public.call_runs%rowtype;
27	  v_entry jsonb;
28	  v_item_id uuid;
29	  v_offset integer;
30	  v_due timestamptz;
31	  v_items integer := 0;
32	  v_mentions integer := 0;
33	  v_retirements integer := 0;
34	  v_commitments integer := 0;
35	begin
36	  if p_call_run_id is null then
37	    raise exception 'ingest requires a call run id';
38	  end if;
39	  if p_user_id is null then
40	    raise exception 'ingest requires a user id';
41	  end if;
42	  if p_state not in ('completed', 'failed', 'canceled') then
43	    raise exception 'ingest requires a terminal state, got %', p_state;
44	  end if;
45	  if p_disposition not in ('answered_extracted', 'answered_no_result', 'not_answered', 'canceled') then
46	    raise exception 'ingest requires a known disposition, got %', p_disposition;
47	  end if;
48	
49	  select * into v_run from public.call_runs where id = p_call_run_id for update;
50	  if not found then
51	    raise exception 'call run % does not exist', p_call_run_id;
52	  end if;
53	  if v_run.user_id <> p_user_id then
54	    raise exception 'call run % does not belong to user %', p_call_run_id, p_user_id;
55	  end if;
56	
57	  if exists (select 1 from public.results where call_run_id = p_call_run_id) then
58	    return jsonb_build_object(
59	      'already_ingested', true,
60	      'disposition', v_run.disposition,
61	      'counts', jsonb_build_object(
62	        'items', 0,
63	        'mentions', 0,
64	        'retirements', 0,
65	        'commitments', 0
66	      ),
67	      'slot_change_requested', p_structured ->> 'slot_change_requested'
68	    );
69	  end if;
70	
71	  insert into public.transcripts (call_run_id, turns, raw, fetched_at)
72	  values (p_call_run_id, coalesce(p_transcript_turns, '[]'::jsonb), p_raw, now())
73	  on conflict (call_run_id) do update
74	    set turns = excluded.turns,
75	        raw = excluded.raw,
76	        fetched_at = now();
77	
78	  insert into public.results (call_run_id, structured, valid, error, fetched_at)
79	  values (p_call_run_id, p_structured, p_result_valid, p_result_error, now())
80	  on conflict (call_run_id) do update
81	    set structured = excluded.structured,
82	        valid = excluded.valid,
83	        error = excluded.error,
84	        fetched_at = now();
85	
86	  for v_entry in select value from jsonb_array_elements(coalesce(p_structured -> 'captured_items', '[]'::jsonb)) loop
87	    if v_entry ->> 'text' is null or btrim(v_entry ->> 'text') = '' then
88	      raise exception 'captured item requires text';
89	    end if;
90	    if not (v_entry ? 'evidence_offset_seconds') then
91	      raise exception 'captured item requires an evidence offset';
92	    end if;
93	    v_offset := (v_entry ->> 'evidence_offset_seconds')::integer;
94	    insert into public.items (user_id, text, source)
95	    values (p_user_id, v_entry ->> 'text', 'call')
96	    returning id into v_item_id;
97	    insert into public.item_mentions (item_id, call_run_id, offset_seconds)
98	    values (v_item_id, p_call_run_id, v_offset);
99	    v_items := v_items + 1;
100	    v_mentions := v_mentions + 1;
101	  end loop;
102	
103	  for v_entry in select value from jsonb_array_elements(coalesce(p_structured -> 'retired_items', '[]'::jsonb)) loop
104	    v_item_id := (v_entry ->> 'item_id')::uuid;
105	    if v_item_id is null then
106	      raise exception 'retired item requires an item id';
107	    end if;
108	    if not (v_entry ? 'evidence_offset_seconds') then
109	      raise exception 'retired item % requires an evidence offset', v_item_id;
110	    end if;
111	    v_offset := (v_entry ->> 'evidence_offset_seconds')::integer;
112	    update public.items
113	       set status = 'retired',
114	           retired_at = coalesce(retired_at, now()),
115	           retired_reason = coalesce(retired_reason, 'retired on the call')
116	     where id = v_item_id
117	       and user_id = p_user_id;
118	    if not found then
119	      raise exception 'retired item % does not belong to user %', v_item_id, p_user_id;
120	    end if;
121	    insert into public.item_mentions (item_id, call_run_id, offset_seconds)
122	    values (v_item_id, p_call_run_id, v_offset);
123	    v_retirements := v_retirements + 1;
124	    v_mentions := v_mentions + 1;
125	  end loop;
126	
127	  for v_entry in select value from jsonb_array_elements(coalesce(p_structured -> 'commitments', '[]'::jsonb)) loop
128	    v_item_id := (v_entry ->> 'item_id')::uuid;
129	    if v_item_id is null then
130	      raise exception 'commitment requires an item id';
131	    end if;
132	    if not (v_entry ? 'evidence_offset_seconds') then
133	      raise exception 'commitment on item % requires an evidence offset', v_item_id;
134	    end if;
135	    v_offset := (v_entry ->> 'evidence_offset_seconds')::integer;
136	    if not exists (select 1 from public.items where id = v_item_id and user_id = p_user_id) then
137	      raise exception 'commitment item % does not belong to user %', v_item_id, p_user_id;
138	    end if;
139	    if v_entry ? 'due' and v_entry ->> 'due' is not null then
140	      v_due := (v_entry ->> 'due')::timestamptz;
141	    else
142	      v_due := null;
143	    end if;
144	    insert into public.commitments (item_id, user_id, call_run_id, due, evidence_offset_seconds)
145	    values (v_item_id, p_user_id, p_call_run_id, v_due, v_offset);
146	    insert into public.item_mentions (item_id, call_run_id, offset_seconds)
147	    values (v_item_id, p_call_run_id, v_offset);
148	    v_commitments := v_commitments + 1;
149	    v_mentions := v_mentions + 1;
150	  end loop;
151	
152	  update public.call_runs
153	     set state = p_state,
154	         disposition = p_disposition,
155	         mood = p_mood,
156	         completed_at = coalesce(p_completed_at, now())
157	   where id = p_call_run_id;
158	
159	  return jsonb_build_object(
160	    'already_ingested', false,
161	    'disposition', p_disposition,
162	    'counts', jsonb_build_object(
163	      'items', v_items,
164	      'mentions', v_mentions,
165	      'retirements', v_retirements,
166	      'commitments', v_commitments
167	    ),
168	    'slot_change_requested', p_structured ->> 'slot_change_requested'
169	  );
170	end;
171	$$;
172	
173	-- The caller is the service role only. Ingestion writes for any user, so an
174	-- authenticated or anonymous session must never reach it.
175	revoke all on function public.ingest_call_result(
176	  uuid, uuid, jsonb, jsonb, jsonb, boolean, text, text, text, text, timestamptz
177	) from public;
178	revoke all on function public.ingest_call_result(
179	  uuid, uuid, jsonb, jsonb, jsonb, boolean, text, text, text, text, timestamptz
180	) from anon;
181	revoke all on function public.ingest_call_result(
182	  uuid, uuid, jsonb, jsonb, jsonb, boolean, text, text, text, text, timestamptz
183	) from authenticated;
184	grant execute on function public.ingest_call_result(
185	  uuid, uuid, jsonb, jsonb, jsonb, boolean, text, text, text, text, timestamptz
186	) to service_role;
187

