const messages = [
  'invalid input syntax for type timestamp with time zone: "2026-09-12 4155550127"',
  'call me on 415/555/0127',
  "call me on 415 555 0127",
  "call me on 415_555_0127",
  "number 4155-55-0127",
  'plain "+1 415 555 0127"',
];
for (const message of messages) {
  const fetchImpl: typeof fetch = () =>
    Promise.resolve(Response.json({ code: "22007", message, details: null, hint: null }, { status: 400 }));
  const thrown = await ingestTerminalRun({
    callRunId: "11111111-1111-4111-8111-111111111111",
    userId: "33333333-3333-4333-8333-333333333333",
