const invalidBody = JSON.parse(await Deno.readTextFile("/tmp/orma-review-t27-r2/testdata/calle/webhook-result-validation-failed.documented.json")).body;

async function drive(label: string, fn: () => Promise<unknown>) {
  try {
    const out = await fn();
    console.log(`${label}: ok ${JSON.stringify(out)}`);
  } catch (error) {
    console.log(`${label}: threw ${(error as Error).message}`);
  }
}

const src = (run: string, structured: unknown, raw: unknown = completed, t = turns) => ({
  callRunId: run, userId: ids.userA, raw, transcriptTurns: t, structuredResult: structured,
});

// Done condition: unmodified completed fixture, then re-ingest twice.
await drive("fixture", () => ingestTerminalRun(src(ids.runFx, completed.structured_result), deps));
await drive("fixture-again-1", () => ingestTerminalRun(src(ids.runFx, completed.structured_result), deps));
await drive("fixture-again-2", () => ingestTerminalRun(src(ids.runFx, completed.structured_result), deps));

// Done condition: augmented fixture with a retirement and a commitment.
const augmented = {
  ...completed.structured_result,
  retired_items: [{ item_id: ids.itemA1, evidence_offset_seconds: 62 }],
  commitments: [{ item_id: ids.itemA2, due: "2026-09-15T10:00:00Z", evidence_offset_seconds: 80 }],
};
await drive("augmented", () => ingestTerminalRun(src(ids.runAug, augmented, { ...completed, structured_result: augmented }), deps));

// Done condition: invalid fixture.
await drive("invalid", () => ingestTerminalRun(src(ids.runInv, invalidBody, { id: invalidBody.data.id, status: "completed", structured_result: null }, []), deps));

// Attack: a schema-conformant spoken due, as the Goal schema asks for.
const spoken = {
  ...completed.structured_result,
  commitments: [{ item_id: ids.itemA2, due: "tomorrow after work", evidence_offset_seconds: 80 }],
};
await drive("spoken-due", () => ingestTerminalRun(src(ids.runDue, spoken, { ...completed, structured_result: spoken }), deps));

// Attack: an RFC 3339 due with nine fraction digits, which PostgreSQL accepts.
const rfc = {
  ...completed.structured_result,
  commitments: [{ item_id: ids.itemA2, due: "2026-09-15T10:00:00.123456789Z", evidence_offset_seconds: 80 }],
};
await drive("rfc3339-due", () => ingestTerminalRun(src(ids.runRfc, rfc, { ...completed, structured_result: rfc }), deps));

// Attack: U+0000 in a captured text. The real raw payload carries the same structured_result.
const nul = { ...completed.structured_result, captured_items: [{ text: "Conti�nental", evidence_offset_seconds: 44 }] };
await drive("nul-raw", () => ingestTerminalRun(src(ids.runNul, nul, { ...completed, structured_result: nul }), deps));
await drive("nul-raw-retry", () => ingestTerminalRun(src(ids.runNul, nul, { ...completed, structured_result: nul }), deps));

// Attack: a transcript turn with empty text.
const blankTurns = [...turns, { offset_seconds: 120, speaker: "user", text: "" }];
await drive("blank-turn", () => ingestTerminalRun(src(ids.runBlank, completed.structured_result, completed, blankTurns), deps));

// Attack: retire another user's real item.
const foreign = { ...completed.structured_result, retired_items: [{ item_id: ids.itemB, evidence_offset_seconds: 62 }] };
await drive("foreign-item", () => ingestTerminalRun(src(ids.runForeign, foreign, { ...completed, structured_result: foreign }), deps));

// Attack: two overlapping ingests of one run. The first run's event POST is slow.
const slow: IngestDeps = {
  ...deps,
  fetch: async (input, init) => {
    const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
    if (url.endsWith("/rest/v1/call_events") && (init?.method ?? "GET") === "POST") {
      await new Promise((r) => setTimeout(r, 1500));
    }
    return fetch(input, init);
  },
};
const first = ingestTerminalRun(src(ids.runRace, completed.structured_result), slow);
await new Promise((r) => setTimeout(r, 400));
const second = ingestTerminalRun(src(ids.runRace, completed.structured_result), deps);
const settled = await Promise.allSettled([first, second]);
console.log(`race: ${JSON.stringify(settled.map((s) => s.status === "fulfilled" ? { already: s.value.alreadyIngested } : { error: String(s.reason) }))}`);

